<?php
namespace PharmaSure\Integrations;
final class Installer{public static function install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$p=$wpdb->prefix.'ps_';$c=$wpdb->get_charset_collate();$normalize=array(\PharmaSure\Core\DatabaseMigrations::class,'normalize_dbdelta_sql');dbDelta(call_user_func($normalize,"CREATE TABLE {$p}integration_configs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,integration_type VARCHAR(30) NOT NULL,adapter_key VARCHAR(100) NOT NULL,display_name VARCHAR(150) NOT NULL,endpoint_url VARCHAR(500) NULL,encrypted_credentials LONGTEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'inactive',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NULL,PRIMARY KEY  (id),UNIQUE KEY tenant_adapter (tenant_id,branch_id,integration_type,adapter_key),KEY tenant_status (tenant_id,status)) $c"));dbDelta(call_user_func($normalize,"CREATE TABLE {$p}integration_deliveries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,config_id BIGINT UNSIGNED NOT NULL,outbox_event_id BIGINT UNSIGNED NULL,direction VARCHAR(10) NOT NULL DEFAULT 'outbound',idempotency_key VARCHAR(100) NOT NULL,event_type VARCHAR(100) NOT NULL,payload LONGTEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',attempt_count INT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME NULL,response_code INT NULL,response_body TEXT NULL,last_error VARCHAR(500) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NULL,PRIMARY KEY  (id),UNIQUE KEY tenant_idempotency (tenant_id,idempotency_key),KEY due (status,next_attempt_at),KEY config_created (tenant_id,config_id,id)) $c"));dbDelta(call_user_func($normalize,"CREATE TABLE {$p}integration_callbacks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL,config_id BIGINT UNSIGNED NOT NULL,provider_event_id VARCHAR(150) NOT NULL,event_type VARCHAR(100) NOT NULL,payload LONGTEXT NOT NULL,signature_valid TINYINT(1) NOT NULL,processed_at DATETIME NULL,status VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY  (id),UNIQUE KEY provider_event (tenant_id,config_id,provider_event_id)) $c"));update_site_option('pharmasure_integrations_db_version',DB_VERSION);}}
